(async()=>{await require('./run.cjs').prepareChromium();const{open}=require('../im_plan/imh'),{pg,close}=await open([{sym:'SOXL'}]);try{const rows=await pg.evaluate(()=>{const out=[];for(const cap of[10000,100000])for(const to of['2026-11-06','2026-11-09','2026-11-10']){const r=RUN({tkr:'SOXL',cap,autoTp:true,to,trace:true});out.push({cap,to,final:r.final,cycles:r.cycles,tax:r.tax});}const a=RUN({tkr:'SOXL',cap:10000,from:'2010-04-01',to:'2026-11-09',autoTp:true,trace:true}),b=RUN({tkr:'SOXL',cap:10000,from:'2010-04-01',to:'2026-11-10',autoTp:true,trace:true});return {rows:out,prefixUnchanged:JSON.stringify(a.trace.tr)===JSON.stringify(b.trace.tr.filter(x=>x[0]<='2026-11-09'))};});fs.writeFileSync('/tmp/jkq-20261111-baseline-cutoff.json',JSON.stringify(rows));console.log(JSON.stringify(rows));}finally{await close();}})().catch(e=>{console.error(e.stack||e);process.exitCode=1;});
